[standards/application/event-driven/STD-APP-EVT-002-dotnet-kafka-producer.md#producer-configuration-structure]

### Producer Configuration Structure

The following C# class defines the complete producer configuration for AWS MSK with IAM authentication:

```csharp
using Confluent.Kafka;
using Amazon.Runtime;
using System.Text;

public class KafkaProducerConfiguration
{
    /// <summary>
    /// AWS MSK broker endpoints (comma-separated for multiple brokers)
    /// </summary>
    public string BootstrapServers { get; set; } = "b-1.msk-cluster.xxx.kafka.us-east-1.amazonaws.com:9098,b-2.msk-cluster.xxx.kafka.us-east-1.amazonaws.com:9098";

    /// <summary>
    /// AWS region where MSK cluster is deployed
    /// </summary>
    public string AwsRegion { get; set; } = "us-east-1";

    /// <summary>
    /// Enable idempotent producer for exactly-once semantics
    /// </summary>
    public bool EnableIdempotence { get; set; } = true;

    /// <summary>
    /// Acknowledgment level (All = leader + replicas)
    /// </summary>
    public Acks Acks { get; set; } = Acks.All;

    /// <summary>
    /// Maximum in-flight requests per connection (max 5 for idempotence)
    /// </summary>
    public int MaxInFlight { get; set; } = 5;

    /// <summary>
    /// Enable gapless guarantee for exactly-once delivery
    /// </summary>
    public bool EnableGaplessGuarantee { get; set; } = true;

    /// <summary>
    /// Compression type for message batches
    /// </summary>
    public CompressionType CompressionType { get; set; } = CompressionType.Snappy;

    /// <summary>
    /// Time to wait before sending batch (improves throughput)
    /// </summary>
    public int LingerMs { get; set; } = 100;

    /// <summary>
    /// Batch size in bytes
    /// </summary>
    public int BatchSize { get; set; } = 16384; // 16KB

    /// <summary>
    /// Request timeout in milliseconds
    /// </summary>
    public int RequestTimeoutMs { get; set; } = 30000;

    /// <summary>
    /// Retry backoff time in milliseconds
    /// </summary>
    public int RetryBackoffMs { get; set; } = 1000;

    /// <summary>
    /// Message send max retries
    /// </summary>
    public int MessageSendMaxRetries { get; set; } = 3;

    /// <summary>
    /// Converts configuration to Confluent ProducerConfig
    /// </summary>
    public ProducerConfig ToProducerConfig()
    {
        var config = new ProducerConfig
        {
            BootstrapServers = BootstrapServers,
            SecurityProtocol = SecurityProtocol.SaslSsl,
            SaslMechanism = SaslMechanism.OAuthBearer,
            EnableIdempotence = EnableIdempotence,
            Acks = Acks,
            MaxInFlight = MaxInFlight,
            EnableGaplessGuarantee = EnableGaplessGuarantee,
            CompressionType = CompressionType,
            LingerMs = LingerMs,
            BatchSize = BatchSize,
            RequestTimeoutMs = RequestTimeoutMs,
            RetryBackoffMs = RetryBackoffMs,
            MessageSendMaxRetries = MessageSendMaxRetries,

            // TLS/SSL settings for AWS MSK
            SslCaLocation = "/etc/ssl/certs/ca-certificates.crt", // Linux
            // For Windows: "C:\\Windows\\System32\\curl-ca-bundle.crt"

            // Client identification
            ClientId = $"{Environment.GetEnvironmentVariable("APP_NAME") ?? "kafka-producer"}-{Environment.MachineName}"
        };

        return config;
    }
}

/// <summary>
/// AWS IAM authentication token provider for Kafka SASL/OAUTHBEARER
/// </summary>
public class AwsIamAuthTokenProvider
{
    private readonly string _region;
    private readonly AWSCredentials _credentials;

    public AwsIamAuthTokenProvider(string region)
    {
        _region = region;
        // Use default credential chain: Environment vars -> ECS/EKS IAM role -> EC2 instance profile
        _credentials = FallbackCredentialsFactory.GetCredentials();
    }

    /// <summary>
    /// Generates AWS IAM authentication token for Kafka broker
    /// </summary>
    public async Task<string> GenerateAuthTokenAsync()
    {
        var immutableCredentials = await _credentials.GetCredentialsAsync();

        var token = new StringBuilder()
            .Append($"{{\"version\":\"2020_10_22\",")
            .Append($"\"host\":\"kafka.{_region}.amazonaws.com\",")
            .Append($"\"user-agent\":\"aws-msk-iam-auth\",")
            .Append($"\"action\":\"kafka-cluster:Connect\"")
            .Append("}}");

        // In production, use AWS.MSK.IAM.AuthTokenGenerator NuGet package
        // This is a simplified example showing the concept
        return Convert.ToBase64String(Encoding.UTF8.GetBytes(token.ToString()));
    }
}
```

