[standards/application/event-driven/STD-APP-EVT-002-dotnet-kafka-producer.md#transactional-outbox-table-schema]

### Transactional Outbox Table Schema

The transactional outbox pattern requires a database table to store events within the same transaction as business entities. This ensures atomicity between database changes and event publishing.

**SQL DDL (PostgreSQL):**

```sql
CREATE TABLE event_outbox (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    topic VARCHAR(255) NOT NULL,
    message_key VARCHAR(500),
    message_value TEXT NOT NULL,
    headers JSONB,
    correlation_id VARCHAR(100) NOT NULL,
    event_type VARCHAR(255) NOT NULL,
    event_version VARCHAR(20) NOT NULL DEFAULT '1.0',
    aggregate_id VARCHAR(100),
    aggregate_type VARCHAR(100),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    published_at TIMESTAMP NULL,
    status VARCHAR(50) NOT NULL DEFAULT 'Pending',
    retry_count INT NOT NULL DEFAULT 0,
    last_error TEXT NULL,
    scheduled_at TIMESTAMP NULL,

    CONSTRAINT chk_status CHECK (status IN ('Pending', 'Published', 'Failed', 'Scheduled'))
);

-- Index for efficient outbox processor queries
CREATE INDEX idx_outbox_status_created ON event_outbox(status, created_at)
    WHERE status IN ('Pending', 'Scheduled');

-- Index for correlation ID lookups (troubleshooting)
CREATE INDEX idx_outbox_correlation_id ON event_outbox(correlation_id);

-- Index for aggregate tracking
CREATE INDEX idx_outbox_aggregate ON event_outbox(aggregate_type, aggregate_id);
```

**Entity Framework Core Model:**

```csharp
using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using Microsoft.EntityFrameworkCore;

[Table("event_outbox")]
[Index(nameof(Status), nameof(CreatedAt), Name = "idx_outbox_status_created")]
[Index(nameof(CorrelationId), Name = "idx_outbox_correlation_id")]
[Index(nameof(AggregateType), nameof(AggregateId), Name = "idx_outbox_aggregate")]
public class EventOutboxEntry
{
    [Key]
    [Column("id")]
    public Guid Id { get; set; } = Guid.NewGuid();

    [Required]
    [Column("topic")]
    [MaxLength(255)]
    public string Topic { get; set; } = string.Empty;

    [Column("message_key")]
    [MaxLength(500)]
    public string? MessageKey { get; set; }

    [Required]
    [Column("message_value")]
    public string MessageValue { get; set; } = string.Empty;

    [Column("headers", TypeName = "jsonb")]
    public string? Headers { get; set; }

    [Required]
    [Column("correlation_id")]
    [MaxLength(100)]
    public string CorrelationId { get; set; } = string.Empty;

    [Required]
    [Column("event_type")]
    [MaxLength(255)]
    public string EventType { get; set; } = string.Empty;

    [Required]
    [Column("event_version")]
    [MaxLength(20)]
    public string EventVersion { get; set; } = "1.0";

    [Column("aggregate_id")]
    [MaxLength(100)]
    public string? AggregateId { get; set; }

    [Column("aggregate_type")]
    [MaxLength(100)]
    public string? AggregateType { get; set; }

    [Required]
    [Column("created_at")]
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

    [Column("published_at")]
    public DateTime? PublishedAt { get; set; }

    [Required]
    [Column("status")]
    [MaxLength(50)]
    public OutboxStatus Status { get; set; } = OutboxStatus.Pending;

    [Required]
    [Column("retry_count")]
    public int RetryCount { get; set; } = 0;

    [Column("last_error")]
    public string? LastError { get; set; }

    [Column("scheduled_at")]
    public DateTime? ScheduledAt { get; set; }
}

public enum OutboxStatus
{
    Pending,
    Published,
    Failed,
    Scheduled
}
```

**DbContext Configuration:**

```csharp
using Microsoft.EntityFrameworkCore;

public class ApplicationDbContext : DbContext
{
    public ApplicationDbContext(DbContextOptions<ApplicationDbContext> options)
        : base(options)
    {
    }

    public DbSet<EventOutboxEntry> EventOutbox { get; set; } = null!;

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);

        modelBuilder.Entity<EventOutboxEntry>(entity =>
        {
            entity.ToTable("event_outbox");

            // Convert enum to string in database
            entity.Property(e => e.Status)
                .HasConversion<string>();

            // Configure JSONB column for PostgreSQL
            entity.Property(e => e.Headers)
                .HasColumnType("jsonb");

            // Partial index for pending/scheduled events only
            entity.HasIndex(e => new { e.Status, e.CreatedAt })
                .HasDatabaseName("idx_outbox_status_created")
                .HasFilter("status IN ('Pending', 'Scheduled')");
        });
    }
}
```

**Migration Command:**

```bash
# Add migration
dotnet ef migrations add AddEventOutboxTable --context ApplicationDbContext

# Apply migration
dotnet ef database update --context ApplicationDbContext
```

