[standards/application/event-driven/STD-APP-EVT-002-dotnet-kafka-producer.md#step-13-create-producer-factory]

#### Step 1.3: Create Producer Factory

Implement a factory to manage producer lifecycle and connection pooling:

```csharp
using Confluent.Kafka;
using Microsoft.Extensions.Options;

public interface IKafkaProducerFactory
{
    IProducer<string, byte[]> CreateProducer();
}

public class KafkaProducerFactory : IKafkaProducerFactory, IDisposable
{
    private readonly KafkaProducerConfiguration _config;
    private readonly ILogger<KafkaProducerFactory> _logger;
    private IProducer<string, byte[]>? _producer;
    private readonly object _lock = new object();

    public KafkaProducerFactory(
        IOptions<KafkaProducerConfiguration> config,
        ILogger<KafkaProducerFactory> logger)
    {
        _config = config.Value;
        _logger = logger;
    }

    public IProducer<string, byte[]> CreateProducer()
    {
        if (_producer != null)
            return _producer;

        lock (_lock)
        {
            if (_producer != null)
                return _producer;

            var producerConfig = _config.ToProducerConfig();

            var builder = new ProducerBuilder<string, byte[]>(producerConfig);

            // Configure AWS IAM authentication callback
            builder.SetOAuthBearerTokenRefreshHandler((producer, token) =>
            {
                try
                {
                    var authProvider = new AwsIamAuthTokenProvider(_config.AwsRegion);
                    var authToken = authProvider.GenerateAuthTokenAsync().GetAwaiter().GetResult();

                    producer.OAuthBearerSetToken(authToken, DateTime.UtcNow.AddMinutes(50).Ticks, "kafka");
                    _logger.LogDebug("AWS IAM token refreshed successfully");
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to refresh AWS IAM token");
                    producer.OAuthBearerSetTokenFailure(ex.Message);
                }
            });

            // Configure error handler
            builder.SetErrorHandler((producer, error) =>
            {
                _logger.LogError("Kafka producer error: {Error}", error.Reason);
            });

            // Configure statistics handler (for monitoring)
            builder.SetStatisticsHandler((producer, statistics) =>
            {
                _logger.LogDebug("Producer statistics: {Statistics}", statistics);
            });

            _producer = builder.Build();
            _logger.LogInformation("Kafka producer initialized successfully");

            return _producer;
        }
    }

    public void Dispose()
    {
        _producer?.Dispose();
    }
}
```

