#### Step 2.1: Create Event Publisher Service

Implement the service that writes events to the outbox table:

```csharp
using System.Text.Json;
using Microsoft.EntityFrameworkCore;

public interface IEventPublisher
{
    Task PublishAsync<TEvent>(string topic, string key, TEvent eventData, Dictionary<string, string>? headers = null) where TEvent : class;
}

public class OutboxEventPublisher : IEventPublisher
{
    private readonly ApplicationDbContext _dbContext;
    private readonly ILogger<OutboxEventPublisher> _logger;

    public OutboxEventPublisher(ApplicationDbContext dbContext, ILogger<OutboxEventPublisher> logger)
    {
        _dbContext = dbContext;
        _logger = logger;
    }

    public async Task PublishAsync<TEvent>(
        string topic,
        string key,
        TEvent eventData,
        Dictionary<string, string>? headers = null) where TEvent : class
    {
        var correlationId = Activity.Current?.Id ?? Guid.NewGuid().ToString();

        var outboxEntry = new EventOutboxEntry
        {
            Topic = topic,
            MessageKey = key,
            MessageValue = JsonSerializer.Serialize(eventData),
            Headers = headers != null ? JsonSerializer.Serialize(headers) : null,
            CorrelationId = correlationId,
            EventType = typeof(TEvent).Name,
            EventVersion = "1.0",
            Status = OutboxStatus.Pending,
            CreatedAt = DateTime.UtcNow
        };

        _dbContext.EventOutbox.Add(outboxEntry);

        _logger.LogInformation(
            "Event added to outbox: Topic={Topic}, Key={Key}, EventType={EventType}, CorrelationId={CorrelationId}",
            topic, key, outboxEntry.EventType, correlationId);
    }
}
```

