[standards/application/event-driven/STD-APP-EVT-002-dotnet-kafka-producer.md#step-22-usage-within-business-transaction]

#### Step 2.2: Usage Within Business Transaction

Example of using the event publisher within a business transaction:

```csharp
public class ClaimService
{
    private readonly ApplicationDbContext _dbContext;
    private readonly IEventPublisher _eventPublisher;

    public ClaimService(ApplicationDbContext dbContext, IEventPublisher eventPublisher)
    {
        _dbContext = dbContext;
        _eventPublisher = eventPublisher;
    }

    public async Task ApproveClaim(Guid claimId)
    {
        // Begin transaction
        using var transaction = await _dbContext.Database.BeginTransactionAsync();

        try
        {
            // Update business entity
            var claim = await _dbContext.Claims.FindAsync(claimId);
            if (claim == null)
                throw new InvalidOperationException($"Claim {claimId} not found");

            claim.Status = ClaimStatus.Approved;
            claim.ApprovedAt = DateTime.UtcNow;

            // Publish event to outbox (same transaction)
            await _eventPublisher.PublishAsync(
                topic: "claims.adjudication.claim-approved",
                key: claimId.ToString(),
                eventData: new ClaimApprovedEvent
                {
                    ClaimId = claimId,
                    ApprovedAt = claim.ApprovedAt.Value,
                    Amount = claim.Amount
                });

            // Save changes (both entity and outbox entry)
            await _dbContext.SaveChangesAsync();

            // Commit transaction
            await transaction.CommitAsync();
        }
        catch (Exception)
        {
            await transaction.RollbackAsync();
            throw;
        }
    }
}
```

