#### Step 2.3: Implement Outbox Processor Background Service

Create a background service that polls the outbox table and publishes events to Kafka:

```csharp
using Polly;
using Polly.Retry;
using System.Text.Json;

public class OutboxProcessorService : BackgroundService
{
    private readonly IServiceProvider _serviceProvider;
    private readonly IKafkaProducerFactory _producerFactory;
    private readonly ILogger<OutboxProcessorService> _logger;
    private readonly AsyncRetryPolicy _retryPolicy;

    public OutboxProcessorService(
        IServiceProvider serviceProvider,
        IKafkaProducerFactory producerFactory,
        ILogger<OutboxProcessorService> logger)
    {
        _serviceProvider = serviceProvider;
        _producerFactory = producerFactory;
        _logger = logger;

        // Configure retry policy with exponential backoff
        _retryPolicy = Policy
            .Handle<Exception>()
            .WaitAndRetryAsync(
                retryCount: 3,
                sleepDurationProvider: attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)),
                onRetry: (exception, timeSpan, retryCount, context) =>
                {
                    _logger.LogWarning(exception,
                        "Retry {RetryCount} after {TimeSpan}s due to error publishing event",
                        retryCount, timeSpan.TotalSeconds);
                });
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _logger.LogInformation("Outbox processor service started");

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                await ProcessPendingEventsAsync(stoppingToken);

                // Poll interval: 5 seconds
                await Task.Delay(TimeSpan.FromSeconds(5), stoppingToken);
            }
            catch (OperationCanceledException)
            {
                // Expected during shutdown
                break;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error in outbox processor loop");
                await Task.Delay(TimeSpan.FromSeconds(10), stoppingToken);
            }
        }

        _logger.LogInformation("Outbox processor service stopping - flushing remaining events");
        await FlushRemainingEventsAsync();
    }

    private async Task ProcessPendingEventsAsync(CancellationToken cancellationToken)
    {
        using var scope = _serviceProvider.CreateScope();
        var dbContext = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();

        // Fetch pending events (batch of 100)
        var pendingEvents = await dbContext.EventOutbox
            .Where(e => e.Status == OutboxStatus.Pending)
            .OrderBy(e => e.CreatedAt)
            .Take(100)
            .ToListAsync(cancellationToken);

        if (!pendingEvents.Any())
            return;

        _logger.LogInformation("Processing {Count} pending events from outbox", pendingEvents.Count);

        var producer = _producerFactory.CreateProducer();

        foreach (var outboxEntry in pendingEvents)
        {
            if (cancellationToken.IsCancellationRequested)
                break;

            await PublishEventAsync(producer, dbContext, outboxEntry, cancellationToken);
        }
    }

    private async Task PublishEventAsync(
        IProducer<string, byte[]> producer,
        ApplicationDbContext dbContext,
        EventOutboxEntry outboxEntry,
        CancellationToken cancellationToken)
    {
        using var activity = Activity.Current?.Source.StartActivity(
            "PublishOutboxEvent",
            ActivityKind.Producer);

        activity?.SetTag("messaging.system", "kafka");
        activity?.SetTag("messaging.destination", outboxEntry.Topic);
        activity?.SetTag("messaging.operation", "publish");

        try
        {
            await _retryPolicy.ExecuteAsync(async () =>
            {
                // Serialize message value to bytes
                var messageBytes = System.Text.Encoding.UTF8.GetBytes(outboxEntry.MessageValue);

                // Build Kafka message with headers
                var message = new Message<string, byte[]>
                {
                    Key = outboxEntry.MessageKey,
                    Value = messageBytes,
                    Headers = new Headers()
                };

                // Add standard headers
                message.Headers.Add("correlation-id", System.Text.Encoding.UTF8.GetBytes(outboxEntry.CorrelationId));
                message.Headers.Add("event-type", System.Text.Encoding.UTF8.GetBytes(outboxEntry.EventType));
                message.Headers.Add("event-version", System.Text.Encoding.UTF8.GetBytes(outboxEntry.EventVersion));

                // Add custom headers from outbox entry
                if (!string.IsNullOrEmpty(outboxEntry.Headers))
                {
                    var customHeaders = JsonSerializer.Deserialize<Dictionary<string, string>>(outboxEntry.Headers);
                    if (customHeaders != null)
                    {
                        foreach (var header in customHeaders)
                        {
                            message.Headers.Add(header.Key, System.Text.Encoding.UTF8.GetBytes(header.Value));
                        }
                    }
                }

                // Publish to Kafka
                var deliveryResult = await producer.ProduceAsync(outboxEntry.Topic, message, cancellationToken);

                activity?.SetTag("messaging.kafka.partition", deliveryResult.Partition.Value);
                activity?.SetTag("messaging.kafka.offset", deliveryResult.Offset.Value);

                _logger.LogInformation(
                    "Event published successfully: Id={Id}, Topic={Topic}, Partition={Partition}, Offset={Offset}",
                    outboxEntry.Id, outboxEntry.Topic, deliveryResult.Partition, deliveryResult.Offset);

                // Mark as published
                outboxEntry.Status = OutboxStatus.Published;
                outboxEntry.PublishedAt = DateTime.UtcNow;
                await dbContext.SaveChangesAsync(cancellationToken);
            });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Failed to publish event after retries: Id={Id}, Topic={Topic}",
                outboxEntry.Id, outboxEntry.Topic);

            // Update outbox entry with failure status
            outboxEntry.RetryCount++;
            outboxEntry.LastError = ex.Message;

            if (outboxEntry.RetryCount >= 3)
            {
                outboxEntry.Status = OutboxStatus.Failed;
                _logger.LogError("Event marked as failed after {RetryCount} attempts: Id={Id}",
                    outboxEntry.RetryCount, outboxEntry.Id);
            }

            await dbContext.SaveChangesAsync(cancellationToken);
            activity?.SetStatus(ActivityStatusCode.Error, ex.Message);
        }
    }

    private async Task FlushRemainingEventsAsync()
    {
        var producer = _producerFactory.CreateProducer();
        producer.Flush(TimeSpan.FromSeconds(30));
        _logger.LogInformation("Producer flushed successfully");
    }
}
```

