#### Step 3.1: Configure Schema Registry Client

```csharp
using Amazon.Glue;
using Amazon.Glue.Model;
using Chr.Avro.Confluent;

public class SchemaRegistryService
{
    private readonly IAmazonGlue _glueClient;
    private readonly string _registryName;
    private readonly ILogger<SchemaRegistryService> _logger;

    public SchemaRegistryService(string registryName, ILogger<SchemaRegistryService> logger)
    {
        _glueClient = new AmazonGlueClient();
        _registryName = registryName;
        _logger = logger;
    }

    public async Task<string> GetSchemaAsync(string schemaName)
    {
        var request = new GetSchemaVersionRequest
        {
            SchemaId = new SchemaId
            {
                RegistryName = _registryName,
                SchemaName = schemaName
            }
        };

        var response = await _glueClient.GetSchemaVersionAsync(request);
        return response.SchemaDefinition;
    }

    public async Task RegisterSchemaAsync(string schemaName, string schemaDefinition)
    {
        var request = new RegisterSchemaVersionRequest
        {
            SchemaId = new SchemaId
            {
                RegistryName = _registryName,
                SchemaName = schemaName
            },
            SchemaDefinition = schemaDefinition
        };

        await _glueClient.RegisterSchemaVersionAsync(request);
        _logger.LogInformation("Schema registered: {SchemaName}", schemaName);
    }
}
```

