```csharp
using System.Diagnostics;

public class TracedEventPublisher : IEventPublisher
{
    private readonly IEventPublisher _inner;
    private static readonly ActivitySource ActivitySource = new("KafkaProducer");

    public TracedEventPublisher(IEventPublisher inner)
    {
        _inner = inner;
    }

    public async Task PublishAsync<TEvent>(
        string topic,
        string key,
        TEvent eventData,
        Dictionary<string, string>? headers = null) where TEvent : class
    {
        using var activity = ActivitySource.StartActivity("PublishEvent", ActivityKind.Producer);

        activity?.SetTag("messaging.system", "kafka");
        activity?.SetTag("messaging.destination", topic);
        activity?.SetTag("messaging.operation", "publish");
        activity?.SetTag("event.type", typeof(TEvent).Name);

        try
        {
            await _inner.PublishAsync(topic, key, eventData, headers);
            activity?.SetStatus(ActivityStatusCode.Ok);
        }
        catch (Exception ex)
        {
            activity?.SetStatus(ActivityStatusCode.Error, ex.Message);
            throw;
        }
    }
}
```

