**ClaimController.cs - API Endpoint Example:**

```csharp
using Microsoft.AspNetCore.Mvc;

[ApiController]
[Route("api/[controller]")]
public class ClaimsController : ControllerBase
{
    private readonly ApplicationDbContext _dbContext;
    private readonly IEventPublisher _eventPublisher;
    private readonly ILogger<ClaimsController> _logger;

    public ClaimsController(
        ApplicationDbContext dbContext,
        IEventPublisher eventPublisher,
        ILogger<ClaimsController> logger)
    {
        _dbContext = dbContext;
        _eventPublisher = eventPublisher;
        _logger = logger;
    }

    [HttpPost("{claimId}/approve")]
    public async Task<IActionResult> ApproveClaim(Guid claimId)
    {
        using var transaction = await _dbContext.Database.BeginTransactionAsync();

        try
        {
            // Update claim status
            var claim = await _dbContext.Claims.FindAsync(claimId);
            if (claim == null)
                return NotFound();

            claim.Status = ClaimStatus.Approved;
            claim.ApprovedAt = DateTime.UtcNow;

            // Publish event to outbox (within same transaction)
            await _eventPublisher.PublishAsync(
                topic: "claims.adjudication.claim-approved",
                key: claimId.ToString(),
                eventData: new ClaimApprovedEvent
                {
                    ClaimId = claimId,
                    ClaimNumber = claim.ClaimNumber,
                    ApprovedAt = claim.ApprovedAt.Value,
                    Amount = claim.Amount,
                    ApproverId = User.Identity?.Name ?? "system"
                },
                headers: new Dictionary<string, string>
                {
                    { "tenant-id", "gainwell-medicaid" },
                    { "event-source", "claim-service" }
                });

            // Commit transaction (both claim and outbox entry)
            await _dbContext.SaveChangesAsync();
            await transaction.CommitAsync();

            _logger.LogInformation(
                "Claim approved and event published: ClaimId={ClaimId}",
                claimId);

            return Ok(new { ClaimId = claimId, Status = "Approved" });
        }
        catch (Exception ex)
        {
            await transaction.RollbackAsync();
            _logger.LogError(ex, "Error approving claim: ClaimId={ClaimId}", claimId);
            return StatusCode(500, "Internal server error");
        }
    }
}

// Event DTOs
public record ClaimApprovedEvent
{
    public Guid ClaimId { get; init; }
    public string ClaimNumber { get; init; } = string.Empty;
    public DateTime ApprovedAt { get; init; }
    public decimal Amount { get; init; }
    public string ApproverId { get; init; } = string.Empty;
}

public class Claim
{
    public Guid Id { get; set; }
    public string ClaimNumber { get; set; } = string.Empty;
    public ClaimStatus Status { get; set; }
    public decimal Amount { get; set; }
    public DateTime? ApprovedAt { get; set; }
}

public enum ClaimStatus
{
    Submitted,
    UnderReview,
    Approved,
    Denied
}
```

**Expected Behavior:**

1. When `POST /api/claims/{id}/approve` is called:
   - Claim status updated in database
   - Event added to `event_outbox` table (same transaction)
   - Both changes committed atomically

2. Outbox processor (background service):
   - Polls `event_outbox` table every 5 seconds
   - Publishes pending events to Kafka topic
   - Marks events as "Published" after broker acknowledgment
   - Retries failed events with exponential backoff

3. Observability:
   - OpenTelemetry traces span entire flow (API → Database → Kafka)
   - Correlation IDs tracked across all operations
   - Structured logs with contextual information
